const ThemeManager={STORAGE_KEY:'daodejing_theme',ICONS:{light:'☀️',dark:'🌙'},init(){this.themeToggle=document.getElementById('themeToggle');if(!this.themeToggle)return;const savedTheme=localStorage.getItem(this.STORAGE_KEY);if(savedTheme){this.setTheme(savedTheme,true);}else{this.detectSystemTheme();}
this.themeToggle.addEventListener('click',()=>this.toggle());window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(!localStorage.getItem(this.STORAGE_KEY)){this.detectSystemTheme();}});requestAnimationFrame(()=>{document.body.style.transition='background-color 0.3s ease, color 0.3s ease';});},detectSystemTheme(){const prefersDark=window.matchMedia('(prefers-color-scheme: dark)').matches;this.setTheme(prefersDark?'dark':'light',true);},toggle(){const currentTheme=document.documentElement.getAttribute('data-theme');const newTheme=currentTheme==='dark'?'light':'dark';this.setTheme(newTheme);},setTheme(theme,skipSave){document.documentElement.setAttribute('data-theme',theme);if(!skipSave){localStorage.setItem(this.STORAGE_KEY,theme);}this.updateIcon();},updateIcon(){if(!this.themeToggle)return;const icon=this.themeToggle.querySelector('.theme-icon');if(!icon)return;const currentTheme=document.documentElement.getAttribute('data-theme');icon.textContent=currentTheme==='dark'?this.ICONS.dark:this.ICONS.light;}};if(typeof module!=='undefined'&&module.exports){module.exports=ThemeManager;}
if(typeof window!=='undefined'){if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>ThemeManager.init());}else{ThemeManager.init();}
window.ThemeManager=ThemeManager;}
